mapper.select:
SELECT FROM tb_item_partner_price p LEFT JOIN tb_material_info m ON m.material_id = p.material_id AND m.tenant_id = p.tenant_id LEFT JOIN tb_customer_info c ON c.customer_id = p.customer_id AND c.tenant_id = p.tenant_id WHERE p.tenant_id = #{tenantId}
AND (m.material_code ILIKE '%' || #{keyword} || '%' OR m.material_name ILIKE '%' || #{keyword} || '%' OR c.customer_code ILIKE '%' || #{keyword} || '%' OR c.customer_name ILIKE '%' || #{keyword} || '%')
AND p.trade_type = #{tradeType}
AND p.start_dt <= CAST(#{effectiveOn} AS DATE) AND (p.end_dt IS NULL OR p.end_dt >= CAST(#{effectiveOn} AS DATE))
AND p.use_at = #{useAt}
ORDER BY p.trade_type, m.material_code, c.customer_code, p.start_dt DESC, p.price_id

WITH source_rows AS (
SELECT #{row.sourceRowNumber}::INTEGER AS source_row_number, #{row.materialCode}::VARCHAR AS material_code, #{row.customerCode}::VARCHAR AS customer_code, #{row.tradeType}::VARCHAR AS trade_type, #{row.startDt}::DATE AS start_dt
) SELECT r.source_row_number AS "sourceRowNumber", m.material_id AS "materialId", m.material_code AS "materialCode", m.material_name AS "materialName", c.customer_id AS "customerId", c.customer_code AS "customerCode", c.customer_name AS "customerName", existing.price_id AS "existingPriceId" FROM source_rows r LEFT JOIN tb_material_info m ON m.tenant_id = #{tenantId} AND m.material_code = r.material_code AND m.delete_status = 'N' AND m.deleted_at IS NULL LEFT JOIN tb_customer_info c ON c.tenant_id = #{tenantId} AND c.customer_code = r.customer_code AND c.use_at = 'Y' LEFT JOIN tb_item_partner_price existing ON existing.tenant_id = #{tenantId} AND existing.material_id = m.material_id AND existing.customer_id = c.customer_id AND existing.trade_type = r.trade_type AND existing.start_dt = r.start_dt ORDER BY r.source_row_number

SELECT price_id
FROM tb_item_partner_price
WHERE tenant_id = #{tenantId}
    AND material_id = #{materialId}
    AND customer_id = #{customerId}
    AND trade_type = #{tradeType}
    AND start_dt = CAST(#{startDt} AS DATE)

    AND price_id != #{excludePriceId}

LIMIT 1
